/* ═════════ ٦-١ القسمةُ والكسورُ الاعتياديّة ═════════ */
units['6-1'] = { kind: 'lesson', title: 'القسمة والكسور الاعتيادية', gens: ['share'], idea: 'أمثّلُ مواقفَ القسمةِ بالكسورِ الاعتياديّة.', vocab: [['الكسرُ الاعتياديّ', 'يمثّلُ أجزاءً متساويةً من كلٍّ أو من مجموعة.'], ['البسط', 'العددُ العلويُّ في الكسر، ويدلُّ على عددِ الأجزاء.'], ['المقام', 'العددُ السفليُّ في الكسر، ويدلُّ على عددِ أجزاءِ الكلّ.']],
  readyText: 'وعاءٌ مملوءٌ بالحليبِ يكفي لملءِ ثلاثةِ أكواب. نقسمُ وعاءً واحدًا على ثلاثةِ أكواب: ١ ÷ ٣', ready: [shareQ('🔹', 'ما كمّيّةُ الحليبِ التي ستوضعُ في كلِّ كوب؟ (١ ÷ ٣)', 1, 3)],
  intro: [{ h: 'الكسرُ يمثّلُ القسمة', p: 183, html: '<p><b>الكسرُ الاعتياديّ</b> يمثّلُ أجزاءً متساويةً من كلٍّ أو من مجموعة، وتستعملُ الكسورُ لتمثيلِ القسمة؛ فإذا قُسمَ وعاءٌ واحدٌ من الحليبِ إلى ٣ أجزاءٍ متساوية، فسيكونُ في كلِّ كوبٍ ' + fr(1, 3) + ' (ثلثُ) الوعاء.</p><p class="big" style="text-align:center">' + fr(1, 3) + ' ← البسطُ ١ ، المقامُ ٣</p><p><b>البسطُ</b> هو العددُ العلويُّ في الكسر، ويدلُّ على عددِ الأجزاء. <b>والمقامُ</b> هو العددُ السفليُّ في الكسر، ويدلُّ على عددِ أجزاءِ الكلّ.</p>' + KB('تذكّرْ', 'تُقسمُ الأشياءُ أو الكمّيّاتُ إلى أجزاءٍ متساويةٍ عندَ استعمالِ الكسور.') },
    { h: '🍕 جرّبِ التقسيمَ بنفسِك', tool: el => shareTool(el, 2, 3) }],
  examples: [
    { ...shareQ('مثال ١', 'طعام: يريدُ تركي وسعودٌ وفهدٌ أن يتقاسموا فطيرتينِ بالتساوي، فكم سيكونُ نصيبُ كلٍّ منهم؟', 2, 3, { p: 183, cfu: true, sol: ['فطيرتانِ تُقسمانِ على ٣ أشخاص: ٢ ÷ ٣', 'نقسمُ كلَّ فطيرةٍ إلى ثلاثةِ أجزاءٍ متساوية، فيأخذُ كلُّ واحدٍ جزءًا من كلِّ فطيرة.', 'نصيبُ كلِّ واحدٍ منهم ' + fr(2, 3) + ' (ثلثا) الفطيرة.'] }), gen: 'share' },
    { ...shareQ('مثال ٢', 'طعام: تريدُ فلوةُ ومرامُ أن تقتسما ٣ كعكاتٍ صغيرةٍ بالتساوي. ما نصيبُ كلٍّ منهما؟', 3, 2, { p: 184, cfu: true, sol: ['٣ ÷ ٢ = ' + fr(3, 2), 'تحصلُ كلٌّ منهما على كعكةٍ كاملة، والكعكةُ المتبقّيةُ تُقسمُ بينهما بالتساوي.', 'إذن تحصلُ كلٌّ منهما على ' + mixed(1, 1, 2) + ' كعكة.'] }), gen: 'share' }],
  ex: [
    ['✅ تأكّدْ', 184, [shareQ('١', 'استُعملَ كيسانِ من طعامِ الطيورِ لملءِ ثلاثةِ أوعيةٍ بالتساوي. ما كمّيّةُ الطعامِ التي وُضعتْ في كلِّ وعاء؟', 2, 3), shareQ('٢', 'وزّعَ مدرّسُ التربيةِ الفنّيّةِ ٣ كيلوجراماتٍ من الصلصالِ على أربعةِ طلابٍ بالتساوي. ما نصيبُ كلٍّ منهم؟', 3, 4),
      { ...shareQ('٣', 'يريدُ أربعةُ أطفالٍ أن يقتسموا قطعَ البسكويتِ المبيّنةَ أدناه (٥ قطع) فيما بينهم بالتساوي. ما نصيبُ كلِّ واحدٍ منهم؟', 5, 4), html: `<div style="font-size:30px;text-align:center">${'🍪'.repeat(5)}</div>` },
      shareQ('٤', 'استُعملتْ ستّةُ أكياسٍ من الترابِ لملءِ ٥ أوعيةٍ لزراعةِ الأزهار. ما كمّيّةُ الترابِ التي وُضعتْ في كلِّ وعاء؟', 6, 5),
      open('٥', 'تحدّثْ: اشرحْ كيف تستعملُ الكسورَ الاعتياديّةَ لتمثيلِ مواقفِ قسمةٍ من واقعِ الحياة، وأعطِ مثالًا على ذلك.', 'الكسرُ ' + fr('أ', 'ب') + ' يعني أ ÷ ب. مثال: ٣ برتقالاتٍ تُقسمُ على ٤ أطفال، فنصيبُ كلِّ طفلٍ ' + fr(3, 4) + ' برتقالة.')]],
    ['✏️ تدرّبْ وحُلَّ المسائل', 185, [shareQ('٦', 'استُعملَ مترٌ من القماشِ لصنعِ رايتينِ للمدرسة. كم تحتاجُ كلُّ رايةٍ من القماش؟', 1, 2, { unit: 'م' }), shareQ('٧', 'اقتسمَ أربعةُ إخوةٍ قطعةَ أرضٍ بالتساوي، ما نصيبُ كلِّ واحدٍ منهم؟', 1, 4),
      shareQ('٨', 'القياس: استُعملتْ ٣ كيلوجراماتٍ من البطاطسِ لصنعِ ٨ أطباق. كم كيلوجرامًا استُعملَ في كلِّ طبق؟', 3, 8), shareQ('٩', 'استُعملتْ حمولةُ شاحنتينِ من العشبِ الاصطناعيِّ لتغطيةِ سبعةِ ملاعب. إذا وُزّعتِ الحمولةُ بالتساوي، فما كمّيّةُ العشبِ الاصطناعيِّ التي وُضعتْ في كلِّ ملعب؟', 2, 7),
      { ...shareQ('١٠', 'يستهلكُ ناصرٌ كمّيّةَ الماءِ الموضّحةَ أدناه (٥ قوارير) في ثلاثةِ أيّام. إذا كان يستهلكُ الكمّيّةَ نفسَها يوميًّا، فكم قارورةً من الماءِ يستهلكُ يوميًّا؟', 5, 3), html: `<div style="font-size:30px;text-align:center">${'🧴'.repeat(5)}</div>` },
      shareQ('١١', 'يُرادُ تقطيعُ حبلٍ طولُه ٦ م إلى خمسِ قطعٍ متساوية. فكم يكونُ طولُ القطعةِ الواحدة؟', 6, 5, { unit: 'م' }),
      num('١٢', 'استُعملتْ أربعةُ لتراتٍ من الدهانِ لطلاءِ ٢٤ كرسيًّا. إذا احتاجَ كلُّ كرسيٍّ إلى الكمّيّةِ نفسِها من الدهان، فكم كرسيًّا يمكنُ طلاؤُه بلترٍ واحد؟', 6, { skill: 'share', sol: ['٢٤ ÷ ٤ = ٦ كراسي لكلِّ لتر', '(وكلُّ كرسيٍّ يحتاجُ ' + fr(4, 24) + ' = ' + fr(1, 6) + ' لتر)'] }),
      shareQ('١٣', 'القياس: صنعتْ جدّتي سبعَ وسائدَ من قطعةِ قماشٍ طولُها ٩ أمتار. ما كمّيّةُ القماشِ التي استُعملتْ في كلِّ وسادة؟', 9, 7, { unit: 'م' }),
      open('١٤', 'مسألةٌ مفتوحة: اكتبْ مسألةَ قسمةٍ من واقعِ الحياةِ تتضمّنُ تقسيمَ أربعةِ أشياءَ بالتساوي، ثم حُلَّ المسألة.', 'مثال: تقاسمَ ٥ أصدقاءَ ٤ فطائرَ بالتساوي: ٤ ÷ ٥ = ' + fr(4, 5) + ' فطيرةٍ لكلٍّ منهم.'),
      mcq('١٥', 'التبريرُ المنطقيّ: قُسمتْ خمسةُ كيلوجراماتٍ من الفراولةِ على عددٍ من الصناديقِ بالتساوي. إذا زادَ عددُ الصناديق، ماذا يحدثُ لكمّيّةِ الفراولةِ التي توضعُ في كلِّ صندوق؟', ['تقلّ', 'تزداد', 'لا تتغيّر'], 0, { sol: ['كلّما زادَ المقامُ (عددُ الصناديق) صغرَ نصيبُ كلِّ صندوق: ' + fr(5, 4) + ' > ' + fr(5, 6) + '؛ وإذا قلَّ عددُ الصناديقِ تزدادُ الكمّيّة.'] }),
      open('١٦', 'اكتبْ مسألةً من واقعِ الحياةِ يكونُ حلُّها ' + fr(2, 15) + '، وصفْ ما يمثّلُه الكسر.', 'مثال: قُسمَ لتران من العصيرِ على ١٥ طالبًا بالتساوي؛ نصيبُ كلِّ طالبٍ ' + fr(2, 15) + ' لتر. البسطُ ٢ هو الكمّيّةُ المقسومة، والمقامُ ١٥ عددُ الطلاب.')]]] };

