/* ═════════ ٦-٢ الكسورُ غيرُ الفعليّة ═════════ */
units['6-2'] = { kind: 'lesson', title: 'الكسور غير الفعلية', gens: ['tomix', 'share'], idea: 'أكتبُ الكسورَ غيرَ الفعليّةِ على صورةِ أعدادٍ كسريّة.',
  readyText: 'قسّمَ خبّازٌ الكعكاتِ التي صنعَها إلى أثلاث، وفي آخرِ النهار، بقيَ لديه ٥ أثلاث.', ready: [{ ...toMixQ('🔹', 5, 3, { text: 'اكتبِ الكمّيّةَ المتبقّيةَ ' + big(fr(5, 3)) + ' على صورةِ عددٍ كسريّ.' }), html: `<div class="row c">${pieSVG(3, 3, 34, '#f5c842')}${pieSVG(2, 3, 34, '#f5c842')}</div>` }],
  intro: [{ h: 'من كسرٍ غيرِ فعليٍّ إلى عددٍ كسريّ', p: 188, html: T2(['كسورٌ غيرُ فعليّة', 'أعدادٌ كسريّة'], [[`${fr(5, 3)} ، ${fr(9, 8)} ، ${fr(12, 12)}`, `${mixed(1, 4, 5)} ، ${mixed(8, 1, 2)}`]]) + '<p>بما أنّ الكسرَ يمثّلُ القسمة، فإنّ ' + fr(5, 3) + ' تعني ٥ ÷ ٣، وإذا أردتَ كتابةَ كسرٍ غيرِ فعليٍّ مكافئٍ لعددٍ كسريّ، فعليك أن تستعملَ القسمة، ثم تعبّرَ عن الباقي على صورةِ كسر.</p>' + KB('مفهومٌ أساسيّ: الكسورُ غيرُ الفعليّة', 'لكتابةِ كسرٍ غيرِ فعليٍّ على صورةِ عددٍ كسريّ، اقسمِ البسطَ على المقام، واكتبِ الكسرَ بحيثُ يكونُ بسطُه الباقي ومقامُه القاسم.<br>٥ ÷ ٣ = ١ والباقي ٢ ← ' + mixed(1, 2, 3)) + KB('تذكّرْ', 'من المهمِّ معرفةُ ما يعنيه الجزءُ الكسريُّ من العددِ الكسريِّ في المواقفِ الحياتيّة.') },
    { h: '🟦 حوّلْ بنفسِك', tool: el => mixedTool(el, '5/3') }],
  examples: [
    { ...toMixQ('مثال ١', 5, 3, { p: 188, cfu: true }), gen: 'tomix' },
    { ...toMixQ('مثال ٢', 20, 10, { p: 189, cfu: true, sol: ['٢٠ ÷ ١٠ = ٢ ولا يوجدُ باقٍ', 'بما أنّ ١٠ تقسمُ العددَ ٢٠ من دونِ باقٍ، فإنّ الناتجَ يُكتبُ ٢'] }), gen: 'tomix' },
    fld('مثال ٣', 'ألعاب: تتّسعُ كلُّ عربةٍ من عرباتِ القطارِ المعلّقِ لـ ٢٤ راكبًا. إذا كان هناك ٥٥ شخصًا، فإنّ عددَ العرباتِ اللازمةِ لحملِهم هو ' + fr(55, 24) + '. اكتبْ ٥٥ ÷ ٢٤ مع باقٍ، ثم بيّنْ معنى العددين.', [['ناتجُ القسمة (عرباتٌ ممتلئة)', 2], ['الباقي (ركّابُ العربةِ الثالثة)', 7]], { p: 189, cfu: true, skill: 'tomix', sol: ['٥٥ ÷ ٢٤ = ٢ والباقي ٧ ← ' + mixed(2, 7, 24), 'عربتانِ ستمتلئانِ بالركّاب، وعربةٌ ثالثةٌ ستحملُ ٧ أشخاص.'] })],
  ex: [
    ['✅ تأكّدْ', 190, [toMixQ('١', 5, 2), toMixQ('٢', 8, 3), toMixQ('٣', 18, 2), toMixQ('٤', 29, 8),
      toMixQ('٥', 12, 5, { text: 'قسّمتْ والدةُ أسماءَ ١٢ قطعةَ شوكولاتةٍ على ٥ أطفال. ما نصيبُ كلِّ طفل؟ اكتبِ الإجابةَ عددًا كسريًّا (١٢ ÷ ٥ = ٢ والباقي ٢).', sol: ['١٢ ÷ ٥ = ٢ والباقي ٢ ← ' + mixed(2, 2, 5), 'يأخذُ كلُّ طفلٍ قطعتينِ كاملتين، وتُقسمُ القطعتانِ الباقيتانِ بينهم فيأخذُ كلُّ طفلٍ ' + fr(2, 5) + ' منهما.'] }),
      open('٦', 'تحدّثْ: بيّنْ كيف تكتبُ كسرًا غيرَ فعليٍّ على صورةِ عددٍ كسريّ، وأعطِ مثالًا يوضّحُ الخطوات.', 'أقسمُ البسطَ على المقام؛ الناتجُ هو العددُ الصحيح، والباقي بسطُ الكسرِ ومقامُه المقسومُ عليه. مثال: ' + fr(11, 4) + ' ← ١١ ÷ ٤ = ٢ والباقي ٣ ← ' + mixed(2, 3, 4))]],
    ['✏️ تدرّبْ وحُلَّ المسائل', 190, [toMixQ('٧', 16, 8), toMixQ('٨', 11, 4), toMixQ('٩', 17, 3), toMixQ('١٠', 13, 10), toMixQ('١١', 23, 5), toMixQ('١٢', 29, 2), toMixQ('١٣', 37, 12), toMixQ('١٤', 35, 6),
      toMixQ('١٥', 26, 5, { text: 'أنتجَ أحدُ مصانعِ القماشِ ' + big(fr(26, 5)) + ' مليونِ مترٍ مربّعٍ العامَ الماضي. اكتبِ الكسرَ على صورةِ عددٍ كسريّ.' }),
      toMixQ('١٦', 35, 16, { text: 'لدى هدى ٣٥ قلمَ رصاص. أرادتْ أن توزّعَها بالتساوي على ١٦ طالبة، فكم قلمًا يكونُ نصيبُ كلِّ طالبة؟ اكتبِ الإجابةَ على شكلِ عددٍ كسريّ.' }),
      fnq('١٧', 'أعطِ مثالًا لعددٍ كسريٍّ أكبرَ من ٥ وأصغرَ من ٨ (مثل ٦ ١/٢)', raw => { const f = parseFrac(raw); if (!f) return { empty: true }; return { ok: !!f.mixed && f.n < f.d && f.v > 5 && f.v < 8, msg: f.mixed ? 'يجبُ أن يكونَ بينَ ٥ و٨.' : 'اكتبْه عددًا كسريًّا مثل ٦ ١/٢' }; }, '٦ ١/٢', { kp: 'frac', sol: ['أيُّ عددٍ كسريٍّ عددُه الصحيحُ ٥ أو ٦ أو ٧، مثل ' + mixed(6, 1, 2)] }),
      ch('١٨', 'اكتشفِ الخطأ: كتبَ راشدٌ وأحمدُ الكسرَ ' + fr(35, 12) + ' على صورةِ عددٍ كسريّ. راشد: ' + mixed(2, 11, 12) + ' ، أحمد: ' + mixed(3, 5, 12) + '. أيُّهما كتبَه في صورةٍ صحيحة؟', ['راشد', 'أحمد'], 0, { sol: ['٣٥ ÷ ١٢ = ٢ والباقي ١١ ← ' + mixed(2, 11, 12), 'أخطأَ أحمدُ؛ لأنّ ٣ × ١٢ = ٣٦ أكبرُ من ٣٥.'] }),
      mcq('١٩', 'الجبر: إذا كان ' + fr('س', 'ص') + ' كسرًا غيرَ فعليّ، أيُّ العباراتِ الآتيةِ صحيحةٌ دائمًا؟', ['س < ص', 'س > ص أو س = ص', 'س ≠ ص'], 1, { sol: ['الكسرُ غيرُ الفعليِّ بسطُه أكبرُ من مقامِه أو يساويه.'] }),
      frq('٢٠', 'تحدٍّ: اكتبْ ' + big(mixed(1, 10, 3)) + ' على صورةٍ لا يكونُ البسطُ فيها أكبرَ من المقام.', '4 1/3', { form: 'mixed', skill: 'tomix', sol: [fr(10, 3) + ' = ' + mixed(3, 1, 3), '١ + ' + mixed(3, 1, 3) + ' = ' + mixed(4, 1, 3)] }),
      open('٢١', 'اكتبْ مسألةً من واقعِ الحياةِ يمكنُ حلُّها بتحويلِ كسرٍ غيرِ فعليٍّ إلى عددٍ كسريّ. ابدأْ بإيجادِ الباقي ثم اكتبْه على صورةِ عددٍ كسريّ، وبيّنْ معنى العددين.', 'مثال: ٧ بيتزا تُقسمُ على ٣ أطفال: ٧ ÷ ٣ = ٢ والباقي ١ ← ' + mixed(2, 1, 3) + '؛ كلُّ طفلٍ يأخذُ بيتزا كاملتين وثلثَ بيتزا.'),
      { ...mcq('٢٢', 'سجّلتْ لمى ألوانَ عددٍ من السيّاراتِ التي شاهدتْها أثناءَ رحلةٍ لها. أيُّ الكسورِ الاعتياديّةِ التاليةِ تمثّلُ عددَ السيّاراتِ الحمراءِ التي شاهدتْها لمى؟', ['١/٦', '٦/١٧', '٦/١١', '٦/٩'], 1, { sol: ['عددُ السيّاراتِ كلِّها: ٥ + ٣ + ٦ + ٣ = ١٧، والحمراء ٦ ← ' + fr(6, 17)] }), html: T2(['اللون', 'الأسود', 'الأزرق', 'الأحمر', 'غيرُ ذلك'], [['عددُ السيّارات', '٥', '٣', '٦', '٣']]) },
      { ...mcq('٢٣', 'تقاسمَ خمسةُ أشخاصٍ التفّاحاتِ التاليةَ (٨ تفّاحات) بالتساوي. كم أخذَ كلٌّ منهم؟', ['تفّاحتين', '١ ٣/٥ تفّاحة', '١ ٥/٨ تفّاحة', 'تفّاحةً واحدة'], 1, { sol: ['٨ ÷ ٥ = ١ والباقي ٣ ← ' + mixed(1, 3, 5)] }), html: `<div style="font-size:28px;text-align:center">${'🍎'.repeat(8)}</div>` }]],
    ['🔁 مراجعةٌ تراكميّة', 191, [shareQ('٢٤', 'تُستعملُ قطعتانِ من الزبدِ لعملِ ٣ حبّاتِ بسكويت، كم من الزبدِ تحتاجُها لعملِ حبّةِ البسكويتِ الواحدة؟', 2, 3),
      calc('٢٥', '6*9+6*2', { text: 'وضّحْ كيف يمكنُك استعمالُ خاصّيّةِ التوزيعِ لإيجادِ قيمةِ العبارة ٦ × (٩ + ٢)', sol: ['٦ × (٩ + ٢) = ٦ × ٩ + ٦ × ٢', '= ٥٤ + ١٢ = ٦٦'] }),
      num('٢٦', 'زرعَ صلاحٌ شجرتَي زيتونٍ جديدتينِ في حديقةِ منزلِه، فأصبحَ لديه ١٥ شجرةَ زيتون. اكتبْ معادلةً لإيجادِ عددِ أشجارِ الزيتونِ التي كانتْ لديه في المزرعةِ سابقًا، ثم حُلَّها.', 13, { sol: ['س + ٢ = ١٥', 'س = ١٣ شجرة'] }),
      num('٢٧', 'حُلَّ المعادلة: س + ٢ = ٩', 7), num('٢٨', 'حُلَّ المعادلة: ل − ٨ = ٤', 12), num('٢٩', 'حُلَّ المعادلة: ٢جـ = ١٢', 6), num('٣٠', 'حُلَّ المعادلة: ١٨ = ٦ت', 3),
      num('٣١', 'تصنعُ العنودُ أكوابًا من السيراميكِ وتبيعُها بمبلغِ ٦ ريالاتٍ للكوبِ الواحد، وقد شاركتْ في معرضٍ لعرضِ منتجاتِها فدفعتْ ٢٤ ريالًا رسومًا للمشاركةِ في المعرض، إذا باعتْ ٢٩ كوبًا، فكم ريالًا ستجمعُ العنودُ بعدَ دفعِها رسومَ المشاركة؟', 150, { unit: 'ريالًا', sol: ['٢٩ × ٦ = ١٧٤ ريالًا', '١٧٤ − ٢٤ = ١٥٠ ريالًا'] })]]] };

/* ═════════ ٦-٣ خطّةُ حلِّ المسألة: التمثيلُ بأشكالِ ڤن ═════════ */
units['6-3'] = { kind: 'lesson', title: 'خطة حل المسألة: التمثيل بأشكال ڤن', gens: ['venn'], idea: 'أحلُّ المسألةَ باستعمالِ خطّةِ التمثيلِ بأشكالِ ڤن.', vocab: [['أشكالُ ڤن', 'أشكالٌ متداخلةٌ تبيّنُ العناصرَ المشتركةَ بينَ مجموعتينِ أو أكثر، وتكونُ العناصرُ المشتركةُ في منطقةِ التداخل.']],
  intro: [{ h: '⚽ مسألةُ الكرتين', p: 192, html: '<p>يلعبُ ١٥ طالبًا كرةَ السلّة، ويلعبُ ١٨ طالبًا من طلابِ الصفِّ نفسِه كرةَ القدم، ويلعبُ ٣ منهم اللعبتينِ معًا. كم طالبًا يلعبُ كرةَ السلّةِ فقط؟ وكم طالبًا يلعبُ كرةَ القدمِ فقط؟</p>' + vennSVG(['١٢', '٣', '١٥'], 'كرةُ السلّةِ فقط', 'كرةُ القدمِ فقط') + T2(['الخطوة', ''], [['افهمْ', 'تعلمُ عددَ الذين يلعبونَ كرةَ السلّة، وعددَ الذين يلعبونَ كرةَ القدم، وعددَ الذين يلعبونَ اللعبتين. المطلوب: عددُ من يلعبُ كلَّ لعبةٍ فقط.'], ['خطّطْ', 'يمكنُ حلُّ المسألةِ باستعمالِ <b>أشكالِ ڤن</b>، وهي أشكالٌ متداخلةٌ تبيّنُ العناصرَ المشتركةَ بينَ مجموعتينِ أو أكثر.'], ['حُلَّ', 'نكتبُ ٣ في منطقةِ التداخل، ثم نطرحُ: كرةُ السلّةِ فقط: ١٥ − ٣ = ١٢ ، كرةُ القدمِ فقط: ١٨ − ٣ = ١٥'], ['تحقّقْ', 'تحقّقْ من كلِّ منطقةٍ لتتأكّدَ من تمثيلِ العددِ الصحيحِ من الطلاب: ١٢ + ٣ = ١٥ ✓ ، ١٥ + ٣ = ١٨ ✓']]) },
    { h: '⭕ جرّبْ شكلَ ڤن', tool: vennTool }],
  examples: [fld('مثال', 'كم طالبًا يلعبُ كرةَ السلّةِ فقط؟ وكم طالبًا يلعبُ كرةَ القدمِ فقط؟ (١٥ سلّة، ١٨ قدم، ٣ كلتاهما)', [['كرةُ السلّةِ فقط', 12], ['كرةُ القدمِ فقط', 15]], { p: 192, cfu: true, skill: 'venn', sol: ['١٥ − ٣ = ١٢', '١٨ − ٣ = ١٥'] })],
  ex: [
    ['🧩 حلّلِ الخطّة', 193, [vennQ('١', 'إذا كان عددُ الطلابِ ٣٩ طالبًا، فما عددُ الطلابِ الذين لا يلعبونَ كرةَ القدمِ أو كرةَ السلّة؟', 9, ['عددُ من يلعبُ: ١٢ + ٣ + ١٥ = ٣٠', '٣٩ − ٣٠ = ٩ طلاب']),
      vennQ('٢', 'إذا كان عددُ الطلابِ ٣٩ طالبًا، وبدأَ اثنانِ من الطلابِ الذين لا يلعبونَ أيًّا من اللعبتينِ بلعبِ كرةِ السلّةِ وكرةِ القدمِ معًا، فكم يصبحُ عددُ الطلابِ الذين يلعبونَ كرةَ القدمِ وكرةَ السلّةِ معًا؟', 5, ['٣ + ٢ = ٥ طلاب']),
      open('٣', 'ما التغييرُ الذي سيحدثُ على شكلِ ڤن إذا بدأَ بعضُ طلابِ الصفِّ بممارسةِ رياضةِ كرةِ اليد؟', 'نحتاجُ إلى دائرةٍ ثالثةٍ لكرةِ اليد تتداخلُ مع الدائرتين، فتظهرُ مناطقُ تداخلٍ جديدة.'),
      open('٤', 'اشرحْ كيف تساعدُك خطّةُ التمثيلِ بأشكالِ ڤن على حلِّ المسائل.', 'تنظّمُ المعلوماتِ في مجموعاتٍ وتُظهرُ العناصرَ المشتركةَ بوضوح، فنعرفُ عددَ «فقط» بالطرح.')]],
    ['✏️ تدرّبْ على الخطّة', 193, [vennQ('٥', 'يريدُ أفرادُ عائلةِ حنانَ أن يختاروا المكوّناتِ الإضافيّةَ للفطيرة. إذا كان خمسةُ أشخاصٍ يحبّونَ إضافةَ الخضار، وستّةُ أشخاصٍ يحبّونَ إضافةَ اللحم، و٣ أشخاصٍ يحبّونَ كلتيهما، فكم شخصًا يحبُّ إضافةَ الخضارِ فقط؟', 2, ['٥ − ٣ = ٢']),
      open('٦', 'في المسألة ٥، هل من الممكنِ معرفةُ عددِ أفرادِ عائلةِ حنان؟ فسّرْ إجابتَك.', 'إذا كان كلُّ فردٍ يحبُّ إضافةً واحدةً على الأقلّ فعددُهم ٢ + ٣ + ٣ = ٨، لكنّ المسألةَ لا تذكرُ عددَ من لا يحبُّ أيًّا منهما، فلا يمكنُ التأكّدُ تمامًا.'),
      { ...vennQ('٧', 'يبيّنُ الجدولُ نتائجَ المسحِ الذي أجراه الأستاذُ عبدُالحميد، وشملَ ٢٠ طالبًا من طلابِ صفِّه حولَ نكهةِ المثلّجاتِ التي يفضّلونَها. إذا قالَ جميعُ الطلابِ الذين شملَهم المسحُ إنّهم يحبّونَ نكهةً واحدةً على الأقلّ، فكم طالبًا يحبُّ النكهتين؟', 4, ['١١ + ١٣ = ٢٤', '٢٤ − ٢٠ = ٤ طلابٍ تمَّ عدُّهم مرّتين؛ إذن ٤ يحبّونَ النكهتين.']), html: T2(['النكهة', 'عددُ الطلاب'], [['الشوكولاتة', '١١'], ['الفراولة', '١٣']]) },
      vennQ('٨', 'في مسابقةٍ ثقافيّةٍ شاركتْ ٤٣ طالبةً في إلقاءِ الشعر، وشاركتْ ١٥ طالبةً في كتابةِ القصّةِ القصيرة، وشاركتْ ٣٠ طالبةً في الخطابة. إذا شاركتْ خمسُ طالباتٍ في المسابقاتِ الثلاث، وشاركتْ ٣ طالباتٍ فقط في مسابقتَي الشعرِ والخطابة، وشاركتْ طالبةٌ واحدةٌ فقط في مسابقتَي الشعرِ والقصّةِ القصيرة، ولم يشاركْ أحدٌ في مسابقتَي القصّةِ القصيرةِ والخطابةِ معًا (فقط)، فكم طالبةً شاركتْ في مسابقةِ الخطابةِ فقط؟', 22, ['المشاركاتُ في الخطابةِ ومسابقاتٍ أخرى: ٥ (الثلاث) + ٣ (الشعرُ والخطابة) + ٠ = ٨', 'الخطابةُ فقط: ٣٠ − ٨ = ٢٢ طالبة']),
      vennQ('٩', 'اكتبْ: أظهرَ مسحٌ شملَ ١٠٠ شخصٍ أنّ ٦٧ شخصًا منهم يفضّلونَ السفرَ بالسيّارة، و٥٨ شخصًا يفضّلونَ السفرَ بالطائرة، و٢٥ شخصًا يفضّلونَ كلا النوعين. كم شخصًا يفضّلُ السفرَ بالسيّارةِ فقط؟ وضّحِ الخطوات.', 42, ['نكتبُ ٢٥ في منطقةِ التداخل.', 'السيّارةُ فقط: ٦٧ − ٢٥ = ٤٢ شخصًا', 'تحقّق: ٤٢ + ٢٥ + ٣٣ = ١٠٠ ✓'])]]] };

